"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[3863],{13863:e=>{e.exports=JSON.parse('{"meta":{"title":"Volunteer - iMuslim Life","description":"Help Muslims everywhere pray on time and read the Quran in their own language. Volunteer as a translator, reciter, reviewer, writer, tester or masjid ambassador."},"chip":"Volunteer with us","h1":"Your skills can become a sadaqah jariyah","lede":"Salat-e-Mustaqeem and iMuslim Life are free, with no ads, used every day by Muslims around the world. A few hours of your time can help someone pray on time, understand the Quran in their own language, or find their nearest masjid, again and again.","heroCta":"Email us to volunteer","hadith":{"text":"\u201cWhoever guides someone to goodness will have a reward like the one who does it.\u201d","source":"Prophet Muhammad (peace be upon him), Sahih Muslim 1893"},"why":"Every word you translate is read by people you will never meet. Every recitation you record is heard in homes, cars and masjids. We are a small team, and volunteers are how this work reaches every language and every corner of the world.","rolesH2":"Ways you can help","rolesSub":"Pick what fits you. No experience with apps needed, only sincerity, care and a little time.","roleCta":"I can help","roles":{"translate":{"title":"Translators","text":"Bring the app, the website, duas and weekly stories into your language: Arabic, Urdu, French, Spanish, Turkish, Indonesian, Malay, Bengali, Hindi and more. We check every translation before it goes live.","time":"From 1\u20132 hours a week"},"recite":{"title":"Reciters","text":"If Allah has blessed you with a beautiful voice and correct tajweed, record Quran recitations, duas or the Athan for listeners worldwide. We help with recording tips and editing.","time":"Record at your own pace"},"review":{"title":"Scholars and reviewers","text":"Students of knowledge, imams and teachers: check translations, stories and quiz answers for accuracy and sources, so everything we publish is trustworthy.","time":"Review when you can"},"write":{"title":"Writers and storytellers","text":"Help write the weekly stories of the Prophets, the Companions and the Seerah for families and children, in English, Urdu or another language, always from authentic sources.","time":"One story a month is a big help"},"test":{"title":"Testers","text":"Try new features before release on iPhone, Android or Alexa, and tell us what feels wrong or confusing. Fresh eyes catch what we miss.","time":"A few minutes per release"},"masjid":{"title":"Masjid ambassadors","text":"Help your local masjid publish its iqamah and Jumu\u2019ah times so its community sees them in the app, on the website and on Alexa. Free for every masjid.","time":"One conversation can serve a whole community"}},"stepsH2":"How it works","steps":{"s1":{"title":"Email us","text":"Tell us which role, which languages you know, and a little about yourself."},"s2":{"title":"We reply personally","text":"We get back to you, share a short guide and a first small piece of work."},"s3":{"title":"Your work goes live","text":"After review, your contribution reaches people around the world."}},"promiseH2":"What you can expect from us","promise":{"p1":{"title":"Your time, your pace","text":"No minimum commitment. Help when you can, pause whenever you need to."},"p2":{"title":"Credit if you want it","text":"We are happy to thank you by name, or keep your help between you and Allah. Your choice."},"p3":{"title":"Care for accuracy","text":"Religious content is reviewed and sourced before it is published. You never carry that alone."},"p4":{"title":"Your privacy respected","text":"We use your email only to work with you, and never share it or add you to mailing lists."}},"finalH2":"Ready to help?","finalText":"Send us one email. Even if you are not sure where you fit, write to us and we will find the right place together, in shaa Allah."}')}}]);